mkdir -p "$TMPDIR/scratch" && cat > "$TMPDIR/scratch/Scratch.java" <<'EOF'
import org.apache.commons.lang3.time.DateUtils;
import java.util.*;
import java.util.concurrent.TimeUnit;

public class Scratch {
    public static void main(String[] args) throws Exception {
        TimeZone.setDefault(TimeZone.getTimeZone("America/Los_Angeles"));
        Calendar jan1 = new GregorianCalendar(2008,0,1,7,15,10);
        jan1.set(Calendar.MILLISECOND, 538);
        Calendar jan6 = new GregorianCalendar(2008,0,6,7,15,10);
        jan6.set(Calendar.MILLISECOND, 538);

        System.out.println("jan1 MONTH minutes=" + DateUtils.getFragmentInMinutes(jan1, Calendar.MONTH));
        System.out.println("jan6 MONTH minutes=" + DateUtils.getFragmentInMinutes(jan6, Calendar.MONTH));
        System.out.println("jan1 HOUR_OF_DAY minutes=" + DateUtils.getFragmentInMinutes(jan1, Calendar.HOUR_OF_DAY));
        System.out.println("jan6 HOUR_OF_DAY minutes=" + DateUtils.getFragmentInMinutes(jan6, Calendar.HOUR_OF_DAY));
        System.out.println("jan6 MONTH hours=" + DateUtils.getFragmentInHours(jan6, Calendar.MONTH));
        System.out.println("jan1 MONTH days=" + DateUtils.getFragmentInDays(jan1, Calendar.MONTH));
        System.out.println("jan6 YEAR days=" + DateUtils.getFragmentInDays(jan6, Calendar.YEAR));

        Calendar feb28 = new GregorianCalendar(2008,1,28,0,0,0);
        feb28.set(Calendar.MILLISECOND,0);
        System.out.println("feb28 YEAR days=" + DateUtils.getFragmentInDays(feb28, Calendar.YEAR));
        System.out.println("feb28 MONTH days=" + DateUtils.getFragmentInDays(feb28, Calendar.MONTH));

        try {
            DateUtils.getFragmentInDays(jan1, Calendar.DAY_OF_WEEK);
            System.out.println("no exception for DAY_OF_WEEK");
        } catch (IllegalArgumentException e) {
            System.out.println("IAE for DAY_OF_WEEK: " + e.getMessage());
        }
        System.out.println("MILLISECOND fragment days=" + DateUtils.getFragmentInDays(jan1, Calendar.MILLISECOND));

        // ceiling/round/truncate examples
        Calendar c = new GregorianCalendar(2002,2,28,13,45,1);
        c.set(Calendar.MILLISECOND, 231);
        System.out.println("truncate HOUR: " + DateUtils.truncate(c, Calendar.HOUR_OF_DAY).getTime());
        System.out.println("ceiling HOUR: " + DateUtils.ceiling(c, Calendar.HOUR_OF_DAY).getTime());
        System.out.println("truncate MONTH: " + DateUtils.truncate(c, Calendar.MONTH).getTime());
        System.out.println("ceiling MONTH: " + DateUtils.ceiling(c, Calendar.MONTH).getTime());

        Calendar c45 = new GregorianCalendar(2002,2,28,13,45,45);
        c45.set(Calendar.MILLISECOND,0);
        System.out.println("round MINUTE (45s): " + DateUtils.round(c45, Calendar.MINUTE).getTime());
        Calendar c10 = new GregorianCalendar(2002,2,28,13,45,10);
        c10.set(Calendar.MILLISECOND,0);
        System.out.println("round MINUTE (10s): " + DateUtils.round(c10, Calendar.MINUTE).getTime());

        try {
            DateUtils.truncate(c, Calendar.DAY_OF_WEEK);
        } catch (IllegalArgumentException e) {
            System.out.println("truncate IAE: " + e.getMessage());
        }

        Calendar huge = new GregorianCalendar(280000001,0,1);
        try {
            DateUtils.truncate(huge, Calendar.YEAR);
        } catch (ArithmeticException e) {
            System.out.println("Arithmetic: " + e.getMessage());
        }

        // setDays invalid
        try {
            DateUtils.setDays(new Date(), 35);
        } catch (IllegalArgumentException e) {
            System.out.println("setDays IAE: " + e.getMessage());
        }

        // parseDate
        Date d = DateUtils.parseDate("2008-10-01", "yyyy-MM-dd");
        System.out.println("parsed: " + d);
        try {
            DateUtils.parseDate("not a date", "yyyy-MM-dd");
        } catch (java.text.ParseException e) {
            System.out.println("ParseException: " + e.getMessage());
        }
        try {
            DateUtils.parseDateStrictly("2008-02-942", "yyyy-MM-dd");
        } catch (java.text.ParseException e) {
            System.out.println("ParseException strict: " + e.getMessage());
        }

        // iterator
        Calendar focus = new GregorianCalendar(2002,6,4); // Thursday July 4 2002
        Iterator<Calendar> it = DateUtils.iterator(focus, DateUtils.RANGE_MONTH_SUNDAY);
        Calendar first = null, last = null;
        int count=0;
        while (it.hasNext()) { last = it.next(); if (first==null) first=last; count++; }
        System.out.println("RANGE_MONTH_SUNDAY first=" + first.getTime() + " last=" + last.getTime() + " count=" + count);

        try {
            DateUtils.iterator(focus, 999);
        } catch (IllegalArgumentException e) {
            System.out.println("iterator IAE: " + e.getMessage());
        }

        Iterator<Calendar> it2 = DateUtils.iterator(focus, DateUtils.RANGE_WEEK_SUNDAY);
        try {
            while (true) it2.next();
        } catch (NoSuchElementException e) {
            System.out.println("NoSuchElementException on exhausted iterator");
        }
    }
}
EOF
javac -cp target/classes -d "$TMPDIR/scratch" "$TMPDIR/scratch/Scratch.java" && TZ=America/Los_Angeles java -cp "target/classes:$TMPDIR/scratch" Scratch
